// German texts of catalog.mjs: [English text, German text], in catalog order. The English side must match the T()
// text exactly (the build names any text without a translation and any entry whose English text changed or went
// away). Terms follow the app (src/Filee.App/Assets/i18n/de.json): Vorlage (preset), Modul / optionale Module
// (engines), Ringmenü (donut), Segment (slice), Überwachte Ordner (watch folders), Ablagebereich (drop zone),
// integriert (built in), Einstellungen → Module, preset names as in the app (PDF komprimieren, PDF zusammenführen,
// Vektor-SVG, Linien-SVG, Einzelbilder…); "die PDF" as in the app; du, like the app.

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`,
    `Video und Audio, das Extrahieren von Untertiteln und das Speichern als HEIC`],
  [`older office formats such as DOC, PPT and ODT`, `ältere Office-Formate wie DOC, PPT und ODT`],
  [`rare e-book formats and MOBI/AZW3 output`, `seltene E-Book-Formate und die Ausgabe als MOBI/AZW3`],
  [`EPS and PostScript`, `EPS und PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc und andere Auszeichnungssprachen, Word → Markdown und Markdown → Folien`],

  // Options
  [`quality`, `Qualität`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `Einstellbare Qualität für JPG, WEBP und AVIF: JPG wird standardmäßig mit 90 % gespeichert, die Vorlage JPG 70 % erzeugt kleinere Dateien.`],
  [`resize`, `Größe ändern`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Größe beim Konvertieren ändern, prozentual (etwa auf halbe Größe) oder mit einer Höchstlänge für die lange Kante.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `Legt die im Bild gespeicherte DPI fest, etwa 300 für den Druck.`],
  [`grayscale`, `Graustufen`],
  [`A grayscale preset makes black-and-white copies.`, `Eine Graustufen-Vorlage erstellt Schwarzweiß-Kopien.`],
  [`metadata`, `Metadaten`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `Metadaten (EXIF, XMP, Farbprofil) bleiben standardmäßig erhalten und lassen sich zum Schutz der Privatsphäre entfernen.`],
  [`ICO sizes`, `ICO-Größen`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `ICO-Dateien enthalten standardmäßig 256, 128, 64, 48, 32 und 16 px; die Größen lassen sich in der Vorlage ändern.`],
  [`TIFF compression`, `TIFF-Komprimierung`],
  [`TIFF compression can be chosen (LZW by default).`, `Die TIFF-Komprimierung ist wählbar (standardmäßig LZW).`],
  [`white background`, `weißer Hintergrund`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `JPG kennt keine Transparenz, daher werden transparente Bereiche weiß gefüllt.`],
  [`merge into one PDF`, `in einer PDF zusammenführen`],
  [`The merge preset combines all dropped files into one PDF.`,
    `Die Vorlage „PDF zusammenführen“ fasst alle abgelegten Dateien in einer PDF zusammen.`],
  [`split pages`, `Seiten aufteilen`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `Die Vorlage „PDF aufteilen“ speichert jede Seite als eigene PDF in einem Unterordner.`],
  [`rotate & flip`, `drehen & spiegeln`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `Vorlagen zum Drehen und Spiegeln drehen Bilder nach links, nach rechts oder um 180° und spiegeln sie, nachdem die eigene Ausrichtung des Fotos angewendet wurde.`],
  [`Trace to SVG`, `Vektor-SVG`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `Zwei Vorlagen wandeln ein Bild in Vektorformen um: „Vektor-SVG“ mit bis zu 64 Farben und „Linien-SVG“ in Schwarz für Logos, Unterschriften und Scans. Kein weiteres Programm nötig.`],
  [`remove background`, `Hintergrund entfernen`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `Die Vorlage „Hintergrund entfernen“ macht einen einfarbigen Hintergrund transparent: das Papier hinter einer Unterschrift oder einem Stempel, den Hintergrund eines Logos.`],
  [`page ranges`, `Seitenbereiche`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `Seitenbereiche wie 1-3,5 beschränken die Konvertierung auf die Seiten, die du brauchst.`],
  [`render DPI`, `Auflösung (DPI)`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `Seiten werden standardmäßig mit 150 DPI gerendert; wähle 300 DPI für Druckqualität.`],
  [`one long image`, `ein langes Bild`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `Die Vorlage „Langes Bild“ fügt alle Seiten untereinander zu einem hohen Bild zusammen, etwa um ein ganzes Dokument auf einmal zu posten.`],
  [`compress PDF`, `PDF komprimieren`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `Die Vorlage „PDF komprimieren“ verkleinert eine PDF, die dabei eine PDF bleibt: Bilder werden auf 72, 150 oder 300 dpi verkleinert und Fotos erneut als JPEG gespeichert, während Text, Schriften, Links, Lesezeichen und Formulare erhalten bleiben. Eine PDF, die nicht kleiner wird, bleibt unverändert. Ist Ghostscript installiert, kann Filee es zusätzlich versuchen und das kleinere Ergebnis behalten.`],
  [`a picture per slide`, `ein Bild pro Folie`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `„PPTX (Folien)“ legt ein Bild jeder Seite auf eine eigene Folie in Seitengröße, mit dem Seitentext in den Sprechernotizen. Die Folien sehen genau wie die PDF aus, sind aber nicht bearbeitbar; für bearbeitbaren Text in DOCX konvertieren.`],
  [`vector PDF`, `Vektor-PDF`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `Die PDF bleibt vektorbasiert und ist daher bei jedem Zoom und im Druck scharf.`],
  [`editable`, `bearbeitbar`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `Das Ergebnis enthält echten Text und Absätze zum Bearbeiten, keine Bilder von Seiten.`],
  [`attachments as ZIP`, `Anhänge als ZIP`],
  [`Attachments can be saved separately as one ZIP.`, `Anhänge lassen sich separat als eine ZIP-Datei speichern.`],
  [`one CSV per sheet`, `eine CSV pro Blatt`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `Arbeitsmappen mit mehreren Blättern ergeben eine CSV-Datei pro Tabellenblatt.`],
  [`layout kept`, `Layout bleibt erhalten`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Behält Seitengröße und Ränder, Kopf- und Fußzeilen mit Seitenzahlen, Tabellen, Textfelder, Formen und Bilder bei.`],
  [`no Office needed`, `ohne Office`],
  [`No Microsoft Office or LibreOffice needed.`, `Kein Microsoft Office und kein LibreOffice nötig.`],
  [`no Hancom Office needed`, `ohne Hancom Office`],
  [`No Hancom Office and no approval dialog.`, `Kein Hancom Office und kein Bestätigungsdialog.`],
  [`no AutoCAD needed`, `ohne AutoCAD`],
  [`No AutoCAD or DWG viewer needed.`, `Kein AutoCAD und kein DWG-Viewer nötig.`],
  [`no re-encoding`, `ohne Neukodierung`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Kann das neue Format Bild und Ton unverändert aufnehmen (iPhone-MOV → MP4), wird nur der Container gewechselt: kein Qualitätsverlust, HDR bleibt erhalten, fertig in Sekunden.`],
  [`720p option`, `720p-Option`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `Die Vorlage MP4 720p verkleinert große Videos zum Teilen.`],
  [`extract audio`, `Ton extrahieren`],
  [`Only the sound is saved, without the video track.`, `Nur der Ton wird gespeichert, ohne die Videospur.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `Die Vorlage MP3 128k erzeugt kleinere Dateien, ideal für Sprache.`],
  [`extract`, `entpacken`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `Die Vorlage „Entpacken“ entpackt ein Archiv stattdessen in einen Ordner.`],
  [`pack into one ZIP`, `in eine ZIP packen`],
  [`Any selection of files can be packed into one ZIP.`,
    `Jede Auswahl von Dateien lässt sich in eine ZIP-Datei packen.`],
  [`DRM-free books`, `Bücher ohne DRM`],
  [`Works with DRM-free books only.`, `Funktioniert nur mit Büchern ohne DRM.`],
  [`ALAC in M4A`, `ALAC in M4A`],
  [`M4A can hold lossless ALAC as well as AAC.`, `M4A kann neben AAC auch verlustfreies ALAC enthalten.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `Video-Vorlagen können für kleinere Dateien HEVC (H.265) oder AV1 kodieren; 10-Bit- und HDR-Video bleiben dabei erhalten.`],
  [`hardware encoding`, `Hardwarekodierung`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `Schalte in einer Video-Vorlage „Hardwarebeschleunigung nutzen“ ein, um H.264 und HEVC auf dem Grafikchip zu kodieren (NVENC, Quick Sync, AMF, VideoToolbox oder VA-API): deutlich schneller und stromsparender, bei gleicher Qualität etwas größer. Die Option ist standardmäßig aus, und ohne geeigneten Chip wird das Video wie gewohnt kodiert.`],
  [`every frame`, `jedes Einzelbild`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Normalerweise ergibt ein Video ein einzelnes Standbild. Die Vorlagen „Einzelbilder“ oder „Alle Einzelbilder eines Videos speichern“ in einer PNG- oder JPG-Vorlage speichern jedes Einzelbild (oder jedes n-te) als Bilder in einem Ordner neben dem Video.`],
  [`extract subtitles`, `Untertitel extrahieren`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `Die Vorlage „Untertitel extrahieren“ im Ringmenü für Videos speichert die erste Textuntertitelspur eines Videos als SRT.`],
  [`saved as UTF-8`, `als UTF-8 gespeichert`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `Ergebnisse werden als UTF-8 gespeichert. Koreanische Dateien in CP949 (EUC-KR) werden erkannt und korrekt gelesen.`],
  [`tables to CSV / Excel`, `Tabellen in CSV / Excel`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `Daten in Tabellenform (eine Liste von Datensätzen) lassen sich auch in CSV und Excel und wieder zurück konvertieren.`],
  [`picture preview`, `Bildvorschau`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `PNG oder JPG ergibt ein schattiertes Bild des Modells, von vorne rechts und von oben gesehen.`],
  [`colours and textures`, `Farben und Texturen`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `Farben, Texturen und Materialien bleiben erhalten, wo das Zielformat sie speichern kann. STL behält nur die Form.`],
  [`HDR tone-mapped`, `HDR per Tonemapping`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `HDR-Bildschirmfotos, die Windows als JPEG XR speichert, werden per Tonemapping auf normale Helligkeit gebracht, statt abgeschnitten zu werden.`],
  [`Live Photo video`, `Live-Photo-Video`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `Die Vorlage „Live-Photo-Video extrahieren“ speichert das Video eines iPhone Live Photos (eine LIVP-Datei aus iCloud oder ein Foto mit zugehöriger MOV-Datei) oder eines Android Motion Photos als MP4 oder MOV. Umgekehrt machen die Vorlagen „Live Photo (iPhone)“ und „Motion Photo (Android)“ aus einem kurzen Videoclip ein bewegtes Foto; das ist noch experimentell.`],
  [`WGS 84 longitude / latitude`, `WGS 84, Länge / Breite`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `Ergebnisse sind immer in Längen- und Breitengraden (WGS 84). Shapefiles in UTM, Web Mercator, Lambert oder Albers werden umgerechnet und erscheinen so am richtigen Ort; wird eine Datei in ihr eigenes Format konvertiert, wird sie umprojiziert.`],
  [`save as ZIP`, `als ZIP speichern`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `Ein Shapefile besteht aus fünf Dateien (.shp, .shx, .dbf, .prj und .cpg). Mit „Ergebnis als ZIP speichern“ in einer Vorlage oder für alle Geodaten-Ergebnisse in den Einstellungen bleiben sie in einer ZIP-Datei zusammen.`],
  [`Canon CR2 RAW photo`, `Canon-CR2-RAW-Foto`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `CR2 ist das RAW-Fotoformat, das Canon-Spiegelreflexkameras viele Jahre lang verwendet haben (neuere Canon-Modelle schreiben CR3). Es speichert die unbearbeiteten Sensordaten und lässt damit viel Spielraum für die Bearbeitung.`],
  [`Nikon NEF RAW photo`, `Nikon-NEF-RAW-Foto`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `NEF ist das RAW-Fotoformat von Nikon, verwendet von Nikon-Spiegelreflexkameras und spiegellosen Z-Kameras. Wie andere RAW-Dateien enthält es unbearbeitete Sensordaten und ist um ein Mehrfaches größer als ein JPG.`],

  // Images
  [`Images`, `Bilder`],
  [`images`, `Bilder`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `Fotos und Grafiken, darunter iPhone-HEIC und Live Photos, Photoshop-PSD, Kamera-RAW aller großen Hersteller, animiertes APNG, DICOM und die HDR-Bildschirmfotos von Windows (JPEG XR). Beim Konvertieren Größe ändern, drehen, Qualität und DPI festlegen oder Metadaten entfernen, oder ein Bild als SVG vektorisieren.`],
  [`JPEG image`, `JPEG-Bild`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `JPEG ist das am weitesten verbreitete Fotoformat. Die verlustbehaftete Kompression hält Dateien klein, doch jedes Speichern mit geringerer Qualität verwirft Details, und Transparenz gibt es nicht.`],
  [`PNG image`, `PNG-Bild`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `PNG ist ein verlustfreies Bildformat mit Transparenz, ideal für Bildschirmfotos, Logos und Grafiken mit scharfen Kanten. Als PNG gespeicherte Fotos sind meist deutlich größer als JPG.`],
  [`WebP image`, `WebP-Bild`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `WebP ist Googles Bildformat für das Web. Es unterstützt verlustbehaftete und verlustfreie Kompression sowie Transparenz und ist meist kleiner als JPG oder PNG, doch manche Bildbearbeitungen und Upload-Formulare akzeptieren es noch nicht.`],
  [`AVIF image`, `AVIF-Bild`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `AVIF ist ein modernes Bildformat auf Basis des Videocodecs AV1. Es komprimiert besser als JPG und WebP, wird von älterer Software und älteren Geräten aber noch kaum unterstützt.`],
  [`HEIC / HEIF image`, `HEIC-/HEIF-Bild`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `HEIC (HEIF) ist das Fotoformat, das iPhones und iPads standardmäßig verwenden. Fotos sind oft nur etwa halb so groß wie ein JPG, doch viele Windows-Apps, Websites und ältere Geräte können sie nicht öffnen.`],
  [`GIF image / animation`, `GIF-Bild / -Animation`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `GIF ist ein altes, auf 256 Farben beschränktes Bildformat mit einfacher Animation. Es ist noch immer der universelle Weg, kurze tonlose Loops in Chats, Dokumenten und Fehlerberichten zu teilen.`],
  [`Windows icon`, `Windows-Symbol`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `ICO ist das Symbolformat von Windows. Eine ICO-Datei enthält dasselbe Bild in mehreren Größen (etwa 16, 32, 48 und 256 Pixel), sodass es überall scharf aussieht, von der Taskleiste bis zum Favicon einer Website.`],
  [`Photoshop document`, `Photoshop-Dokument`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `PSD ist das native Format von Adobe Photoshop. Es behält Ebenen, Masken und Korrektureinstellungen und eignet sich daher gut zur Bearbeitung, lässt sich aber von den meisten Bildbetrachtern und Websites nicht öffnen.`],
  [`macOS icon`, `macOS-Symbol`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `ICNS ist das Symbolformat von macOS. Wie ICO bündelt es mehrere Größen eines Bildes, bis zu 1024×1024 für Retina-Displays, und wird für App-Symbole auf dem Mac verwendet.`],
  [`Camera RAW`, `Kamera-RAW`],
  [`Windows only`, `nur Windows`],
  [`the photo of the Live Photo`, `das Foto des Live Photos`],
  [`the video of the Live Photo`, `das Video des Live Photos`],

  // Vector graphics
  [`Vector graphics`, `Vektorgrafiken`],
  [`vector graphics`, `Vektorgrafiken`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, Windows-Metadateien, Illustrator, EPS/PostScript und Zeichnungen aus CorelDRAW, Visio und LibreOffice Draw. SVG wird auch zu DXF oder DWG für CAD.`],
  [`SVG vector graphic`, `SVG-Vektorgrafik`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `SVG ist ein XML-basiertes Vektorgrafikformat. Formen und Text bleiben in jeder Größe scharf, ideal für Logos und Symbole im Web, doch viele Apps und Upload-Formulare akzeptieren nur Pixelbilder.`],
  [`Encapsulated PostScript`, `Encapsulated PostScript`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `EPS ist ein Vektorformat aus Druck und Gestaltung, oft für Logos und Illustrationen, die an Druckereien gehen. Die meisten modernen Apps können es ohne PostScript-Interpreter nicht anzeigen.`],
  [`AI files saved with PDF content (Illustrator's default)`, `AI-Dateien mit PDF-Inhalt (Standard in Illustrator)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `PDFs in Bilder, bearbeitbare Word- oder HWPX-Dokumente, PowerPoint-Folien, Text oder ein Comic-Archiv umwandeln sowie zusammenführen, aufteilen, komprimieren oder Seiten auswählen.`],
  [`PDF document`, `PDF-Dokument`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `PDF ist der Standard für Dokumente, die überall gleich aussehen müssen. Schriften, Layout und Bilder sind fest, und die Datei öffnet sich auf jedem Gerät. Genau das macht PDFs auch schwer zu bearbeiten.`],
  [`one page`, `eine Seite`],

  // Documents
  [`Documents`, `Dokumente`],
  [`documents`, `Dokumente`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Word-Dokumente ohne Microsoft Office, chinesische OFD-E-Rechnungen, ältere und seltene Textverarbeitungsformate mit dem optionalen Modul LibreOffice sowie gespeicherte E-Mails (EML und Outlook-MSG).`],
  [`Word document`, `Word-Dokument`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `DOCX ist seit Word 2007 das Format von Microsoft Word (Office Open XML). Es ist das gängigste Format für bearbeitbare Dokumente wie Berichte, Briefe und Formulare.`],
  [`Word 97–2003 document`, `Word-97–2003-Dokument`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `DOC ist das Binärformat von Word 97–2003. Alte Archive, amtliche Formulare und Altsysteme erzeugen es noch, doch es wird von DOCX abgelöst.`],
  [`E-mail message`, `E-Mail-Nachricht`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `EML ist eine einzelne als Datei gespeicherte E-Mail (MIME-Format) mit Kopfzeilen, Nachricht und Anhängen. Die meisten Mail-Programme, darunter Outlook und Thunderbird, können sie öffnen.`],
  [`Outlook message`, `Outlook-Nachricht`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `MSG ist die Datei, die Microsoft Outlook speichert, wenn du eine E-Mail herausziehst. Nur Outlook öffnet sie, daher ist sie auf einem PC ohne Outlook oder auf dem Smartphone schwer zu lesen.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `Koreanisches HWP/HWPX`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Koreanische Hancom-Hangul-Dokumente ohne Hancom Office: HWP ↔ HWPX, in PDF, Bilder, Word, Text, Markdown und HTML sowie HWPX aus Word, Excel, PowerPoint, Markdown und PDF.`],
  [`Hangul document (HWP)`, `Hangul-Dokument (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `HWP ist das Dokumentformat von Hancom Office Hangul (한글), der Standard-Textverarbeitung in koreanischen Behörden, Schulen und vielen Unternehmen. Außerhalb Koreas können es nur wenige Programme öffnen.`],
  [`Hangul document (HWPX)`, `Hangul-Dokument (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `HWPX ist das offene, XML-basierte Format von Hancom Hangul (OWPML, koreanischer Standard KS X 6101). Koreanische Behörden stellen vom binären HWP-Format darauf um.`],

  // Spreadsheets
  [`Spreadsheets`, `Tabellen`],
  [`spreadsheets`, `Tabellen`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Excel-, OpenDocument- und CSV/TSV-Tabellen in PDF mit Seitenanpassung wie in Excel oder ineinander, ohne Excel.`],
  [`Excel workbook`, `Excel-Arbeitsmappe`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `XLSX ist seit Excel 2007 das Arbeitsmappenformat von Microsoft Excel. Eine Arbeitsmappe kann mehrere Tabellenblätter mit Formeln, Formatierung, Diagrammen und Bildern enthalten.`],
  [`Excel 97–2003 workbook`, `Excel-97–2003-Arbeitsmappe`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `XLS ist das binäre Arbeitsmappenformat von Excel 97–2003. Viele ältere Systeme sowie Bank- und Buchhaltungsexporte erzeugen es noch.`],
  [`Comma-separated values`, `Kommagetrennte Werte`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `CSV ist reiner Text mit einer Tabellenzeile pro Zeile. Jede Tabellenkalkulation, Datenbank und Programmiersprache liest es, doch es kennt keine Formatierung, keine Formeln und keine mehreren Blätter.`],

  // Presentations
  [`Presentations`, `Präsentationen`],
  [`presentations`, `Präsentationen`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint in PDF, Bilder und HWPX ohne PowerPoint; ältere PPT-, ODP- und Keynote-Dateien mit dem optionalen Modul LibreOffice.`],
  [`PowerPoint presentation`, `PowerPoint-Präsentation`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `PPTX ist seit PowerPoint 2007 das Format von Microsoft PowerPoint. Es enthält Folien mit Text, Bildern, Formen, Tabellen, Notizen und Animationen.`],
  [`PowerPoint 97–2003 presentation`, `PowerPoint-97–2003-Präsentation`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `PPT ist das Binärformat von PowerPoint 97–2003. Alte Vorlesungsfolien und archivierte Präsentationen liegen oft noch als PPT vor.`],

  // Text & markup
  [`Text & markup`, `Text & Markup`],
  [`text and markup`, `Text und Markup`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Reiner Text, Markdown, HTML und gespeicherte Webseiten (MHTML) in PDF, Word, HWPX und EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter und andere Auszeichnungssprachen nutzen das optionale Modul Pandoc, das auch Markdown in PowerPoint-Folien umwandelt.`],
  [`Plain text`, `Reiner Text`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `TXT ist reiner Text ohne Formatierung, das einfachste und portabelste Dokumentformat. Unterscheiden kann sich nur die Zeichenkodierung (UTF-8, UTF-16 oder eine alte Codepage).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Markdown ist eine schlanke Auszeichnung in reinem Text: # für Überschriften, * für Listen, ** für Fettdruck. Es ist beliebt für Notizen, README-Dateien und Dokumentation und auch ohne Darstellung gut lesbar.`],
  [`Web page (HTML)`, `Webseite (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `HTML ist die Sprache von Webseiten. Eine gespeicherte .html-Datei öffnet sich in jedem Browser, doch ihr Aussehen hängt vom Browser und von verlinkten Styles und Bildern ab, die offline fehlen können.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `LOG-Dateien und Skripte (PY, PAC, BAT, COMMAND) werden als Text gelesen und nie ausgeführt`],
  [`the saved page, with its pictures`, `die gespeicherte Seite mit ihren Bildern`],

  // Data
  [`Data`, `Daten`],
  [`data files`, `Datendateien`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML und XML ineinander sowie Tabellen in CSV und Excel und zurück. vCard-Kontakte in CSV und zurück, auch von alten Handys. Nichts zu installieren.`],
  [`JSON data`, `JSON-Daten`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `JSON ist das Datenformat des Webs: Objekte, Listen, Text und Zahlen als reiner Text. APIs, Apps und Einstellungsdateien verwenden es überall.`],
  [`YAML data`, `YAML-Daten`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `YAML enthält dieselbe Art von Daten wie JSON, geschrieben mit Einrückung statt Klammern. Konfigurationsdateien für Docker, Kubernetes, CI-Pipelines und viele Apps sind YAML.`],
  [`vCard contacts`, `vCard-Kontakte`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `vCard (.vcf) ist das Standarddateiformat für Kontakte. Smartphones, Outlook, Google Kontakte und iCloud exportieren Adressbücher als vCard, oft viele Kontakte in einer Datei.`],

  // E-books
  [`E-books & comics`, `E-Books & Comics`],
  [`e-books and comics`, `E-Books und Comics`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook und Comic-Archive (CBZ, CBR, CB7…) in PDF, EPUB, Word und mehr sowie KEPUB für Kobo-Reader. Nur Bücher ohne DRM.`],
  [`EPUB e-book`, `EPUB-E-Book`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `EPUB ist der offene Standard für E-Books. Der Text passt sich jedem Bildschirm an, und die meisten E-Reader und Lese-Apps unterstützen es; Kindle nimmt EPUB über „Send to Kindle“ an.`],
  [`Kindle / Mobipocket e-book`, `Kindle-/Mobipocket-E-Book`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `MOBI ist das ältere Mobipocket-E-Book-Format, das Amazon Kindle jahrelang verwendet hat. In älteren E-Book-Sammlungen ist es noch verbreitet, doch Amazon setzt inzwischen auf AZW3/KFX und EPUB.`],

  // Video
  [`Video`, `Video`],
  [`video`, `Video`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Alle gängigen Videoformate in MP4 (H.264, HEVC oder AV1), WebM, MOV, MKV, AVI, GIF oder APNG, mit 720p-Option, Hardwarekodierung auf dem Grafikchip, Tonextraktion als MP3 oder M4A und allen Einzelbildern als Bilder. Nutzt das optionale Modul FFmpeg.`],
  [`MPEG-4 video`, `MPEG-4-Video`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `MP4 (MPEG-4 Part 14) ist das kompatibelste Videoformat. Es läuft auf Smartphones, Fernsehern, in Browsern und auf jeder Videoplattform, meist mit H.264- oder H.265-Video und AAC-Ton.`],
  [`QuickTime movie`, `QuickTime-Film`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `MOV ist Apples QuickTime-Videoformat, verwendet von iPhones und Macs. Es enthält meist H.264- oder HEVC-Video, doch manche Schnittprogramme, Fernseher und Websites kommen mit MP4 besser zurecht.`],
  [`Matroska video`, `Matroska-Video`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `MKV (Matroska) ist ein flexibler offener Container, der viele Video-, Audio- und Untertitelspuren aufnehmen kann. Er ist bei Filmen und Aufnahmen beliebt, doch Smartphones, Fernseher und Schnittprogramme spielen ihn nicht immer ab.`],
  [`WebM video`, `WebM-Video`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `WebM ist ein offenes Videoformat für Browser (VP8/VP9- oder AV1-Video mit Vorbis- oder Opus-Ton). Bildschirmaufnahmen und Downloads sind oft WebM, doch viele Schnittprogramme und Geräte erwarten MP4.`],
  [`AVI video`, `AVI-Video`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `AVI ist Microsofts Videocontainer aus den 1990er-Jahren. Camcorder, ältere Kameras und Archive enthalten noch AVI-Dateien, die oft groß sind und auf Smartphones schlecht unterstützt werden.`],
  [`one still frame or every frame`, `ein Standbild oder jedes Einzelbild`],

  // Audio
  [`Audio`, `Audio`],
  [`audio`, `Audio`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Musik, Aufnahmen und Sprachmemos in MP3, M4A, WAV, FLAC, OGG, Opus, AAC oder verlustfreies WavPack und TTA. APE, DSD und DTS werden ebenfalls gelesen. Nutzt das optionale Modul FFmpeg.`],
  [`MP3 audio`, `MP3-Audio`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `MP3 ist das klassische komprimierte Audioformat. Praktisch jeder Player, jedes Autoradio und jedes Smartphone spielt es ab, daher ist es die sicherste Wahl zum Teilen von Musik, Podcasts und Aufnahmen.`],
  [`MPEG-4 audio`, `MPEG-4-Audio`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `M4A ist eine MPEG-4-Audiodatei, meist AAC, verwendet von iTunes, iPhone-Sprachmemos und vielen Aufnahmegeräten. Sie klingt bei kleiner Größe gut, doch manche Player und Autoradios nehmen nur MP3.`],
  [`WAV audio`, `WAV-Audio`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `WAV ist unkomprimierter Ton (meist PCM) für Aufnahme und Bearbeitung. Es klingt genau wie die Quelle, braucht in CD-Qualität aber etwa 10 MB pro Minute.`],
  [`FLAC lossless audio`, `Verlustfreies FLAC-Audio`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `FLAC ist verlustfrei komprimierter Ton: Dateien werden ohne Qualitätsverlust etwa halb so groß wie WAV, daher ist es das Lieblingsformat für Musiksammlungen und Hi-Res-Downloads.`],

  // Subtitles
  [`Subtitles`, `Untertitel`],
  [`subtitles`, `Untertitel`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML und MicroDVD ineinander ohne Modul, gespeichert als UTF-8; SSA und SCC werden gelesen. Koreanische SMI- und SRT-Dateien in CP949 werden korrekt gelesen. Untertitel aus einem Video holt FFmpeg heraus.`],
  [`SubRip subtitles`, `SubRip-Untertitel`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `SRT (SubRip) ist die gängigste Untertiteldatei: nummerierte Einträge mit Start- und Endzeit und reinem Text. Fast jeder Player, jedes Schnittprogramm und jede Videoplattform akzeptiert es.`],
  [`Advanced SubStation Alpha subtitles`, `Advanced-SubStation-Alpha-Untertitel`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `ASS (Advanced SubStation Alpha) ist das gestaltete Untertitelformat von Anime-Fansubs und Aegisub, mit Schriften, Farben, Positionen und Effekten. Viele Geräte und Websites nehmen nur einfaches SRT.`],
  [`WebVTT subtitles`, `WebVTT-Untertitel`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `WebVTT (.vtt) ist das Untertitelformat von HTML5-Video. Web-Player, YouTube und Online-Kursplattformen verwenden es.`],
  [`SAMI subtitles (SMI)`, `SAMI-Untertitel (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `SAMI (.smi) ist Microsofts HTML-ähnliches Untertitelformat. In Korea ist es noch immer die klassische Untertiteldatei, oft in der alten Kodierung CP949 gespeichert, die neuere Player als Zeichensalat anzeigen.`],

  // Archives
  [`Archives`, `Archive`],
  [`archives`, `Archive`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `ZIP, 7Z, RAR, TAR, Disk-Images und viele weitere Archivformate mit dem mitgelieferten Modul 7-Zip neu packen oder entpacken, oder beliebige Dateien in eine ZIP-Datei packen.`],
  [`ZIP archive`, `ZIP-Archiv`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `ZIP ist das universelle Archivformat. Windows, macOS, Smartphones und fast jedes Upload-Formular öffnen es ohne zusätzliche Software.`],
  [`7-Zip archive`, `7-Zip-Archiv`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `7Z ist das offene Archivformat von 7-Zip. Die LZMA2-Kompression erzeugt meist kleinere Dateien als ZIP, doch nicht jedes System und jede Website kann es öffnen.`],
  [`RAR archive`, `RAR-Archiv`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `RAR ist das proprietäre Archivformat von WinRAR, verbreitet bei Downloads, die in Teile aufgeteilt sind. Aktuelle Windows-11-Versionen können RAR öffnen, aber nicht erstellen, und viele Tools akzeptieren nur ZIP.`],
  [`Any files`, `Beliebige Dateien`],

  // CAD
  [`CAD drawings`, `CAD-Zeichnungen`],
  [`CAD drawings [in running text]`, `CAD-Zeichnungen`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `AutoCAD-DWG und -DXF: ineinander oder in PDF, SVG und PNG konvertieren, ohne AutoCAD.`],
  [`AutoCAD drawing`, `AutoCAD-Zeichnung`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `DWG ist das native Zeichnungsformat von AutoCAD und die gängigste CAD-Datei in Architektur und Ingenieurwesen. Ohne AutoCAD oder einen DWG-Viewer lässt sie sich schwer öffnen oder weitergeben.`],
  [`Drawing Exchange Format`, `Drawing Exchange Format`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `DXF (Drawing Exchange Format) ist das Austauschformat von Autodesk für CAD-Zeichnungen. Laserschneider, CNC-Software und die meisten CAD-Programme lesen es, daher ist es der übliche Weg, Zeichnungen zwischen Programmen zu übertragen.`],

  // 3D
  [`3D models`, `3D-Modelle`],
  [`3D models [in running text]`, `3D-Modelle`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF und PLY ineinander und FBX in jedes davon, mit Farben, Texturen und Materialien, wo das Format sie speichert, sowie in ein schattiertes PNG- oder JPG-Bild. Nichts zu installieren.`],
  [`glTF binary (GLB)`, `glTF-Binärdatei (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `GLB ist die Ein-Datei-Variante von glTF, dem 3D-Format für Web, AR und Spiele-Engines. Meshes, Materialien und Texturen stecken in einer einzigen kompakten Datei.`],
  [`STL 3D model`, `STL-3D-Modell`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `STL ist die klassische Datei für den 3D-Druck. Sie speichert nur die Dreiecke einer Form, ohne Farben oder Einheiten, und jeder Slicer und jedes CAD-Programm liest sie.`],
  [`Wavefront OBJ model`, `Wavefront-OBJ-Modell`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `OBJ (Wavefront) ist ein 3D-Format in reinem Text, das fast jedes 3D-Programm öffnet. Materialien und Texturen liegen daneben in einer .mtl-Datei und Bildern.`],

  // Fonts
  [`Fonts`, `Schriftarten`],
  [`fonts`, `Schriftarten`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Desktop- und Webschriften: TTF, OTF, WOFF, WOFF2 und EOT ineinander.`],
  [`TrueType font`, `TrueType-Schrift`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `TTF (TrueType) ist das gängigste Desktop-Schriftformat unter Windows und macOS. Installiere die Schrift, um sie in jeder App zu verwenden.`],
  [`OpenType font`, `OpenType-Schrift`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `OTF (OpenType) ist ein Schriftformat von Adobe und Microsoft. OpenType-Schriften mit PostScript-Konturen (CFF) sind bei professionellen Schriften verbreitet und unterstützen Funktionen wie Ligaturen.`],
  [`Web font (WOFF2)`, `Webschrift (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `WOFF2 ist das komprimierte Webschriftformat, das alle modernen Browser unterstützen. Es ist meist etwa 30 % kleiner als WOFF, sodass Seiten schneller laden.`],

  // Geospatial
  [`Geospatial data`, `Geodaten`],
  [`geospatial data`, `Geodaten`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `Karten und GPS-Daten: GeoJSON, KML, KMZ, GPX und Shapefile ineinander und in CSV, Excel und JSON sowie eine CSV mit Koordinaten zurück in eine Kartendatei. Nur Vektordaten (Punkte, Linien und Flächen), immer in Längen- und Breitengraden gespeichert. Nichts zu installieren.`],
  [`one row per feature, with its coordinates`, `eine Zeile pro Objekt, mit seinen Koordinaten`],
  [`a CSV with longitude and latitude columns or WKT`, `eine CSV mit Spalten für Länge und Breite oder WKT`],

  // Camera RAW
  [`Camera RAW photo`, `Kamera-RAW-Foto`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `Kamera-RAW-Dateien (CR2, CR3, NEF, ARW, DNG, RAF, ORF und mehr) enthalten die unbearbeiteten Sensordaten eines Fotos. Sie bewahren die meisten Details für die Bearbeitung, sind aber groß und brauchen spezielle Software zum Ansehen.`],

  // Conversion guides
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `JPG ist die sichere Wahl, wenn eine Website, eine ältere Windows-App oder jemand ohne iPhone deine Fotos braucht. Ein ganzer Stapel HEIC-Fotos wird auf einmal konvertiert, und jedes JPG landet neben seinem Original.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Wähle PNG, wenn du das Foto weiterbearbeiten willst, ohne eine weitere Runde JPG-Kompression. PNG ist verlustfrei, rechne also mit Dateien, die um ein Mehrfaches größer sind als das HEIC-Original.`],

  // Conversion guides
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `HEIC speichert ein Foto bei gleicher Qualität auf etwa der Hälfte des Platzes eines JPG, so wie iPhones Fotos speichern. Zum Speichern als HEIC braucht es das kostenlose Modul FFmpeg (ca. 100 MB, einmalig in der App heruntergeladen). EXIF, Farbprofil und Ausrichtung bleiben erhalten.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `Von Websites gespeicherte Bilder sind oft WebP. Die Konvertierung in PNG behält die volle Qualität und jede Transparenz, sodass das Ergebnis in jeder Bildbearbeitung, jeder Präsentation und jedem Dokument funktioniert.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Wähle JPG, wenn das Bild ein Foto ist und die Dateigröße zählt, etwa für Upload-Formulare, die WebP ablehnen.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `Als PNG gespeicherte Bildschirmfotos und exportierte Fotos können viele Megabyte groß sein. Fotos werden als JPG meist deutlich kleiner; für Bildschirmfotos mit viel Text und für Logos bleibt PNG oft das bessere Format.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `Die Konvertierung von JPG in PNG holt keine durch die JPG-Kompression verlorenen Details zurück, verhindert aber weitere Verluste: Jede spätere Bearbeitung und jedes Speichern bleibt verlustfrei. Konvertiere, bevor du ein Bild retuschierst oder in einer Bildbearbeitung Transparenz hinzufügst.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `AVIF-Bilder von modernen Websites und Smartphones lassen sich in vielen älteren Programmen, Bildbetrachtern und Upload-Formularen nicht öffnen. JPG öffnet sich überall, bei etwas größeren Dateien.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `WebP ist ideal für Websites: Fotos werden deutlich kleiner als JPG, und Grafiken behalten ihre Transparenz. Die Vorlage WEBP speichert mit Qualität 85, ein guter Kompromiss fürs Web.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Gescannte Seiten, Belege und Fotos von Dokumenten müssen oft als eine PDF verschickt werden. Lege die Bilder auf der Vorlage „PDF zusammenführen“ ab, um eine einzige PDF zu erhalten, oder auf PDF für eine PDF pro Bild. Standardmäßig übernimmt jede Seite die Größe ihres Bildes.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Eine ICO-Datei deckt alles ab, was Windows für Desktop-, Explorer- und Taskleistensymbole braucht, und funktioniert auch als Favicon einer Website. Beginne mit einem quadratischen PNG von mindestens 256×256 px für das schärfste Ergebnis.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Ein Mac-App-Symbol unter Windows zu erstellen erfordert meist zusätzliche Tools; Filee macht aus einem PNG direkt eine ICNS-Datei. Verwende ein quadratisches PNG mit 1024×1024 px, damit die Retina-Größen scharf bleiben.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Teile ein Photoshop-Design mit Leuten ohne Photoshop: Das PNG zeigt das Bild wie gespeichert, mit zusammengefügten sichtbaren Ebenen und erhaltener Transparenz. PNG kann keine Ebenen speichern, behalte also die PSD zum Bearbeiten.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `Filee liest die RAW-Dateien von Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One und weiteren und entwickelt sie mit Standardeinstellungen. So kommst du schnell zu teilbaren JPGs eines Shootings; für kreative Bearbeitung nutze zuerst einen RAW-Editor.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Lege die CR2-Dateien einer ganzen Speicherkarte auf einmal ab: Filee konvertiert sie parallel und speichert jedes JPG neben seiner RAW-Datei. Neuere Canon-Kameras schreiben CR3, das Filee ebenfalls liest.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `NEF-Dateien sind zu groß und zu ungewöhnlich, um sie so zu verschicken. Als JPG werden sie zu kleinen Fotos, die sich überall anzeigen lassen; nutze für Messenger JPG 70 % oder eine Vorlage für halbe Größe. Nikons NRW-Dateien von Coolpix-Kameras funktionieren genauso.`],
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Viele Apps, Präsentationen und Upload-Formulare akzeptieren kein SVG. Filee rendert die Vektorzeichnung in ein PNG mit Transparenz; komprimierte SVGZ-Dateien funktionieren ebenfalls.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `SVG in PDF bleibt vektorbasiert: Linien und Text bleiben bei jedem Zoom und im Druck scharf, und die Datei bleibt klein. Praktisch, um Logos und Diagramme an eine Druckerei zu schicken oder in Dokumente einzufügen.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `EPS kann nur ein PostScript-Interpreter anzeigen; Filee nutzt dafür Ghostscript. Die PDF behält die Vektorgrafik, öffnet sich also überall und wird weiterhin scharf gedruckt. PostScript-Dateien (.ps) funktionieren genauso.`],
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Jede Seite wird zu einem eigenen JPG, eine 10-seitige PDF ergibt also 10 Bilder. Praktisch für Chats, Folien und Social-Media-Beiträge, die Bilder, aber keine PDFs annehmen.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `PNG hält Text und Linien ohne JPG-Artefakte scharf, passend für Folien, Diagramme, Noten und Seiten, die du kommentieren oder in eine Präsentation einfügen willst.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `Filee macht aus der PDF ein Word-Dokument mit echten Absätzen statt Seitenbildern, sodass du Tippfehler korrigieren oder den Text weiterverwenden kannst. Komplexe Layouts brauchen eventuell Nacharbeit, und eine gescannte PDF, die nur Seitenbilder enthält, hat keinen Text zum Extrahieren.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `Filee geht selbstständig den Weg PDF → Word → EPUB, sodass sich der Text an den Bildschirm eines Smartphones oder E-Readers anpasst. Das funktioniert am besten mit PDFs, die echten Text enthalten. Überschriften kommen als normale Absätze an, und gescannte Seiten haben keinen Text zum Konvertieren.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `Filee übernimmt den Text der PDF in ein Word-Dokument, schreibt es als HWPX und speichert das dann als HWP, alles mit integrierten Modulen. Das funktioniert bei PDFs mit echtem Text. Komplexe Layouts brauchen eventuell Nacharbeit, und gescannte Seiten haben keinen Text zum Übernehmen.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `Filee macht aus der PDF zuerst ein Word-Dokument und dann Markdown und behält Absätze, Überschriften und Fettdruck, wo es sie unterscheiden kann. Nützlich für Notizen, Wikis oder zum Einfügen des Textes in andere Tools. Gescannte Seiten haben keinen Text zum Konvertieren.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Koreanische Behörden verlangen Dokumente oft im Hangul-Format. Filee konvertiert den Text der PDF in eine HWPX-Datei, die du in Hancom Hangul öffnen und bearbeiten kannst, ohne Hancom Office für die Konvertierung; wandle sie danach in HWP um, wenn ein Formular das alte Format verlangt.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `Praktisch, wenn eine PDF in PowerPoint gezeigt oder einer bestehenden Präsentation hinzugefügt werden soll: Jede Seite wird zu einer Folie, die genau wie die PDF aussieht, und der Seitentext wartet in den Sprechernotizen. Die Folien sind Bilder; um den Wortlaut zu ändern, konvertiere die PDF stattdessen in DOCX.`],
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `Kein Microsoft Word und kein LibreOffice nötig: Filee liest die DOCX-Datei selbst und setzt die Seiten mit Kopf- und Fußzeilen, Tabellen und Bildern. Lege mehrere Dokumente auf der Vorlage „PDF zusammenführen“ ab, um sie in einer PDF zu vereinen.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `Alte Word-97–2003-Dokumente aus Archiven, amtlichen Formularen oder Altsystemen werden zu PDFs, die sich überall öffnen. Dasselbe Modul konvertiert auch ODT-, RTF-, WPS-, WordPerfect-, Lotus-Word-Pro-, AbiWord- und Apple-Pages-Dateien.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Speichere E-Mails als PDF für Unterlagen, Rechnungen oder Rechtsakten: Die PDF zeigt Absender, Empfänger, Datum, Betreff und Nachricht und öffnet sich überall ohne Mail-Programm.`],
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `Filee setzt HWP-Seiten mit rhwp, einem quelloffenen Hangul-Modul, sodass weder Hancom Office noch dessen Bestätigungsdialog im Spiel sind. Nützlich, um koreanische Dokumente an Leute zu schicken, die HWP nicht öffnen können.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Mach aus einem Hangul-Dokument eine Word-Datei, die Kolleginnen und Kollegen im Ausland bearbeiten können. Text, Absätze und Tabellen werden übernommen; Layouts mit vielen frei positionierten Objekten solltest du kurz in Word prüfen.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `HWPX, das neuere XML-basierte Hangul-Format, wird wie HWP konvertiert: Das integrierte Modul rhwp setzt die Seiten, komplett offline. Praktisch, um HWPX-Formulare von Behörden als PDF zu archivieren.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Manche Systeme und neuere Abläufe akzeptieren nur HWPX. Filee konvertiert binäres HWP mit rhwp in HWPX, ohne Hancom Office, und erledigt einen ganzen Stapel alter Dokumente in einem Durchgang.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `Ältere Hangul-Versionen und manche Einreichungsportale erwarten noch .hwp. Filee konvertiert HWPX mit rhwp zurück in HWP, sodass du nicht jede Datei in Hangul öffnen und neu speichern musst.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `Filees eigener HWPX-Writer überträgt das Word-Layout: Seitengröße und Ränder, Kopf- und Fußzeilen mit Seitenzahlen, Tabellen mit verbundenen Zellen, Rahmen und Schattierung, Textfelder, Formen und Bilder. Jede geschriebene Datei wird in den Tests mit drei unabhängigen HWPX-Lesern geprüft.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `Für Behörden und Formulare, die noch .hwp verlangen. Filee schreibt das Word-Dokument mit dem eigenen Writer als HWPX und konvertiert das mit rhwp in HWP, beides integriert, sodass für die Konvertierung kein Hancom Office nötig ist.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Jede Seite des Word-Dokuments wird zu einem JPG (Filee setzt das Dokument dafür zuerst als PDF), praktisch, um eine Seite online zu posten oder schnell eine Vorschau zu schicken. Word ist nicht nötig.`],
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Jedes sichtbare Tabellenblatt wird zu einem eigenen Abschnitt, mit Zahlenformaten, Schriften, Füllungen, Rahmen und verbundenen Zellen, wie Excel sie zeigt. Breite Blätter werden wie mit Excels „Alle Spalten auf einer Seite darstellen“ auf die Seitenbreite skaliert, und fixierte Überschriftenzeilen wiederholen sich auf jeder Seite.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `CSV enthält nur eine Tabelle, daher schreibt Filee eine CSV-Datei pro Tabellenblatt. Zellen werden als Werte exportiert, bereit für Datenbanken, Skripte und Importformulare.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `Eine XLSX-Arbeitsmappe kann Formatierung, Formeln und weitere Blätter enthalten, die CSV nicht kennt. Wähle alle deine CSV-Exporte aus und lege sie auf einmal ab, um eine Arbeitsmappe pro Datei zu erhalten, ohne den Importdialog von Excel.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Aktualisiere alte Excel-97–2003-Arbeitsmappen ohne Excel oder LibreOffice: Die Konvertierung ist integriert. XLSX-Dateien sind meist kleiner, können keine Makros enthalten und öffnen sich in jeder aktuellen Tabellenkalkulation.`],
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Jede Folie wird zu einer PDF-Seite in Foliengröße, mit Text, Formen, Bildern, Tabellen und dem Masterdesign. Praktisch, um Präsentationen zu verteilen oder dort hochzuladen, wo PowerPoint-Dateien nicht akzeptiert werden. Animationen und Sprechernotizen sind nicht Teil der PDF.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `Alte PowerPoint-97–2003-Präsentationen werden zu PDFs, die jeder öffnen, drucken oder hochladen kann. Keynote- (.key), ODP- und WPS-Präsentationen (DPS) werden genauso konvertiert.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Jede Folie wird zu einem JPG, bereit für Social-Media-Beiträge, Vorschaubilder, Chatnachrichten oder ein Schnittprogramm. Wähle stattdessen PNG, wenn die Folien viel kleinen Text haben.`],
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Überschriften, Listen (auch Aufgabenlisten), Tabellen, Code, Zitate, Links, Bilder, Fußnoten und Formeln werden auf A4-Seiten gesetzt, ohne Pandoc, LaTeX oder Browser. Ein schneller Weg, Notizen und README-Dateien mit Leuten zu teilen, die kein Markdown lesen.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Integriert, kein Pandoc nötig. Überschriften, Listen, Tabellen, Links und Fußnoten werden übernommen, sodass du das Dokument in Word weiter bearbeiten und neu formatieren kannst.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `Reiner Text wird zu einer sauberen A4-PDF mit einem Absatz pro Zeile. Filee erkennt UTF-8 und UTF-16 sowie alte koreanische Textdateien (CP949), sodass alte Logs und Notizen nicht zu Zeichensalat werden.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Speichere eine Webseite oder einen HTML-Bericht als PDF, die überall gleich aussieht und sich archivieren oder drucken lässt. Filee konvertiert auf deinem PC gespeicherte .html-Dateien, und mehrere davon lassen sich in einer PDF zusammenführen.`],
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `Eine PDF hat ein festes Seitenlayout, praktisch, um ein E-Book zu drucken, am PC zu lesen oder an ein Gerät ohne EPUB-Reader zu schicken.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Bring eine alte Kindle-/Mobipocket-Bibliothek in EPUB, damit sie sich in Apple Books, Google Play Books, Kobo und den meisten Lese-Apps öffnet. Diese Richtung ist integriert, Calibre ist also nicht nötig.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `Das E-Book-Programm Calibre schreibt die MOBI- und AZW3-Dateien. Aktuelle Kindles nehmen über „Send to Kindle“ auch EPUB an, MOBI ist also vor allem für ältere Kindle-Geräte und -Apps nützlich.`],
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Speichere den Ton einer Vorlesung, eines Konzerts oder Interviews als MP3, das überall läuft: im Auto, auf einem alten Player oder in einem Transkriptionstool.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `Videos von iPhone und Mac sind MOV-Dateien. Als MP4 laufen sie auf Android-Smartphones, Smart-TVs, in älteren Windows-Apps und in Upload-Formularen, die MOV ablehnen. Bild und Ton passen meist unverändert in MP4, daher wechselt Filee nur den Container: kein Qualitätsverlust, HDR bleibt erhalten, fertig in Sekunden. Die Vorlage MP4 720p verkleinert 4K-Clips zum Teilen.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `MKV-Aufnahmen, etwa aus OBS, lassen sich oft nicht in Schnittprogramme importieren oder auf Fernsehern abspielen, während MP4 fast überall akzeptiert wird. Die Konvertierung läuft lokal, lange Aufnahmen müssen also nie hochgeladen werden.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `Bildschirmaufnahmen und aus dem Browser gespeicherte Videos sind oft WebM, womit viele Schnittprogramme, ältere Player und Messenger schlecht umgehen. MP4 läuft fast überall, und ein ganzer Stapel Clips wird auf einmal konvertiert.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Mach aus einem kurzen Clip ein animiertes GIF für Chats, Dokumentation oder Fehlerberichte. Halte ihn kurz: GIF speichert jedes Einzelbild als Bild mit 256 Farben, lange oder hochauflösende Videos ergeben also sehr große Dateien.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `Ein auf JPG abgelegtes Video ergibt ein Standbild. Um ein Vorschaubild auszuwählen oder einen Clip Bild für Bild durchzugehen, nutze die Vorlage „Einzelbilder (JPG)“: Die Bilder landen in einem Ordner neben dem Video, jedes Einzelbild oder jedes n-te. Ein Video, das mehr als 100.000 Bilder ergeben oder die Festplatte füllen würde, wird vor dem Start abgelehnt.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `AVI-Dateien von alten Camcordern und Kameras sind groß und nutzen oft Codecs, die Smartphones und Fernseher nicht mehr abspielen. Ein MP4 mit moderner Kompression ist meist deutlich kleiner und läuft überall.`],
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `Eine WAV-Aufnahme braucht etwa 10 MB pro Minute; als MP3 nur einen Bruchteil davon, und sie läuft trotzdem auf jedem Gerät.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Behalte deine verlustfreie FLAC-Sammlung zu Hause und kopiere MP3s auf das Smartphone, einen USB-Stick fürs Auto oder einen älteren Player, der kein FLAC abspielt. Ganze Alben werden in einem Durchgang konvertiert.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `iPhone-Sprachmemos, iTunes-Downloads ohne DRM und viele Aufnahmegeräte erzeugen M4A. MP3 akzeptiert jeder Player, jedes Autoradio und jedes Upload-Formular.`],
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `Packe RAR-Archive als ZIP neu für Leute, Upload-Formulare und Systeme, die nur ZIP annehmen. WinRAR ist nicht nötig, weder zum Lesen der RAR- noch zum Schreiben der ZIP-Datei.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `7Z komprimiert oft besser, doch ZIP öffnet sich auf jedem Computer und Smartphone ohne zusätzliche Software. Konvertiere, wenn du ein Archiv an jemanden ohne 7-Zip schickst.`],
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `Schicke Zeichnungen an Kunden, Baustellenteams oder Druckereien ohne AutoCAD: Eine PDF öffnet sich auf jedem PC und Smartphone. Mehrere Zeichnungen lassen sich in einer PDF zusammenführen.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `DXF-Dateien aus CAD-Programmen, Laserschneid-Aufträgen oder dem Austausch von Entwürfen werden zu PDFs, die jeder öffnen und drucken kann. SVG und PNG gibt es auch, etwa für Vorschauen im Web.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `DXF ist das Austauschformat, das Laserschneider, CNC-Software und die meisten CAD-Programme lesen. Mit DWG → DXF öffnest du AutoCAD-Zeichnungen in diesen Programmen, und DXF zurück in DWG funktioniert ebenfalls.`],
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Hoste eine Schrift selbst auf deiner Website: WOFF2 ist das komprimierte Webschriftformat, das jeder moderne Browser unterstützt, meist etwa 30 % kleiner als WOFF. Prüfe, ob die Lizenz der Schrift die Einbettung im Web erlaubt.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Manche älteren Programme, Schneide- und Stickmaschinen sowie Spiele-Engines akzeptieren nur TrueType-Schriften. Konvertiere eine ganze OTF-Schriftfamilie in einem Durchgang in TTF, ohne Schrifteditor.`],
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Nutze „Linien-SVG“ für Logos, Unterschriften und Scans: Die Tinte wird zu einer schwarzen Form auf transparentem Hintergrund. „Vektor-SVG“ behält bis zu 64 Farben für Symbole und Illustrationen. Fotos werden zu flachen Farbflächen, Vektorisieren eignet sich also am besten für Zeichnungen.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `Ein JPG eines Logos oder einer gescannten Skizze wird zu einem SVG, das in jeder Größe scharf bleibt, bereit für einen Schneideplotter, eine Website oder eine Druckerei. JPG-Rauschen wird zu kleinen Flecken; senke also den Detailgrad in der Vorlage, wenn das Ergebnis unruhig wirkt.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `Laserschneider, CNC-Software und CAD-Programme lesen DXF. Filee schreibt die Umrisse des SVG in Millimetern, eine 100 mm breite Form bleibt also 100 mm breit. Kurven werden zu feinen Polylinien. Füllungen, Bilder und Filter werden weggelassen.`],
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `Aus Outlook gezogene E-Mails sind MSG-Dateien, die nur Outlook öffnet. Als PDF behalten sie Absender, Empfänger, Datum, Betreff und Nachricht und öffnen sich überall. Outlook ist nicht nötig.`],
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `YAML ist von Hand leichter zu lesen und zu bearbeiten, deshalb nutzen Konfigurationsdateien es. Schlüssel behalten ihre Reihenfolge, und Text, der sonst als Zahl oder true/false gelesen würde, wird in Anführungszeichen gesetzt.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Mach aus einer Konfigurationsdatei JSON für eine API, ein Skript oder ein Tool, das nur JSON liest. Anker und Aliase werden aufgelöst, und eine Datei mit mehreren Dokumenten wird zu einem Array. Kommentare fallen weg, da JSON keine kennt.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Eine JSON-Liste von Datensätzen wird zu einer Tabelle, die du in Excel öffnen kannst: eine Zeile pro Datensatz, eine Spalte pro Schlüssel. Eine Hülle wie {"users": […]} wird durchschaut. Daten, die keine Tabelle sind, enden mit einer Meldung statt mit einer kaputten Datei.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Bring ein Adressbuch in Excel oder ein Mailing-Tool: eine Zeile pro Kontakt mit Name, Organisation, E-Mail, Telefon, Adresse und Geburtstag. Kontakte von alten koreanischen Handys in CP949 werden korrekt gelesen.`],
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `Web-Player und Online-Kursplattformen wollen WebVTT. Timing, Zeilenumbrüche und Kursivschrift werden übernommen, und es ist kein Modul nötig.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Viele Player, Fernseher und Schnittprogramme lesen kein SMI, und alte koreanische SMI-Dateien erscheinen oft als Zeichensalat. Filee erkennt CP949, wählt die Sprache mit den meisten Zeilen und speichert ein sauberes UTF-8-SRT.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Lehnt ein Fernseher, ein Smartphone oder eine Videoplattform gestaltete ASS-Untertitel ab, funktioniert einfaches SRT. Fett, kursiv, unterstrichen und Farben bleiben erhalten; Positionen, Schriften und Effekte fallen weg.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Hol die Untertitel aus einem Film, um sie zu bearbeiten oder zu übersetzen. Die erste Textuntertitelspur wird als SRT gespeichert; bildbasierte Untertitel (DVD, Blu-ray) lassen sich nicht in Text umwandeln. Benötigt das kostenlose Modul FFmpeg.`],
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Öffne eine Druckdatei in einem 3D-Programm, das OBJ bevorzugt. STL hat keine Einheiten, daher liest Filee sie als Millimeter und schreibt auch OBJ in Millimetern, mit Y nach oben wie in den meisten 3D-Programmen.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `Slicer für 3D-Drucker nehmen STL. Flächen jeder Form werden in Dreiecke zerlegt, und aus Y oben wird Z oben, damit ein aufrechtes Modell auf dem Druckbett steht. STL behält nur die Form, Farben und Texturen bleiben also im OBJ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Bring ein Modell aus dem Web oder einer Spiele-Engine in ein Programm, das OBJ liest. Die .mtl-Datei und die Texturen werden neben die .obj-Datei geschrieben, halte sie also zusammen.`],

  // FAQ
  [`Is Filee really free?`, `Ist Filee wirklich kostenlos?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Ja. Filee ist kostenlos und quelloffen unter der MIT-Lizenz: keine Werbung, keine Wasserzeichen, kein Konto, keine Testphase und keine eigenen Grenzen für Dateianzahl oder Dateigröße.`],
  [`Does it work offline? Are my files uploaded?`, `Funktioniert es offline? Werden meine Dateien hochgeladen?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Jede Konvertierung läuft auf deinem eigenen PC, und Dateien werden nie hochgeladen. Das Internet wird nur genutzt, um ein optionales Modul herunterzuladen oder nach Updates zu suchen, daher bleiben vertrauliche Dokumente, Fotos und Aufnahmen auf deinem Computer.`],
  [`Which file formats does Filee support?`, `Welche Dateiformate unterstützt Filee?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `Filee liest {formatTotal} Dateiformate in {categoryCount} Kategorien: {categoryList}. {builtinTotal} davon funktionieren direkt nach der Installation; die übrigen nutzen ein kostenloses optionales Modul. Der Formatkatalog listet jedes Format und seine Zielformate auf.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `Brauche ich Microsoft Office, Hancom Office oder LibreOffice?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF.`,
    `Nein. Word-, Excel- und PowerPoint-Dateien (DOCX, XLSX, XLS, CSV, PPTX) und koreanische HWP/HWPX-Dokumente werden von in Filee integrierten Modulen konvertiert. Filee nutzt Office und Hancom Office nicht, selbst wenn sie installiert sind; LibreOffice ist nur ein optionaler Download in der App für ältere Formate wie DOC, PPT, ODT und RTF.`],
  [`What are the optional engines?`, `Was sind die optionalen Module?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `Große Module sind nicht im Installationsprogramm enthalten. Wähle sie auf der Modulseite des Installationsprogramms aus oder lade sie in Filee herunter, wann immer du sie brauchst: {engineDetails}. Sie werden in Filees eigenem Ordner gespeichert und lassen sich jederzeit entfernen, und die App zeigt ihre Versionen, die Download-Geschwindigkeit und die Restzeit. Ist FFmpeg, Calibre, Pandoc, Ghostscript oder LibreOffice bereits auf deinem PC (im PATH, auch über Scoop, oder im Ordner „Programme“), nutzt Filee diese Version, überspringt den Download und weist darauf hin, wenn sie älter ist als die getestete Version. Unter Einstellungen → Module → Eigene Version… wählst du eine bestimmte aus.`],
  [`Does installing Filee need administrator rights?`, `Braucht die Installation von Filee Administratorrechte?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Nur einmal, bei der Installation. Das Installationsprogramm legt Filee für alle Benutzer im Ordner „Programme“ ab und fügt unter Windows 11 „Mit Filee konvertieren“ oben im Explorer-Menü hinzu. Filee selbst läuft danach unter deinem normalen Benutzerkonto. Für eine stille Installation starte das Installationsprogramm mit /VERYSILENT /SUPPRESSMSGBOXES. Wenn du keine Programme installieren darfst, nutze die portable ZIP-Datei: irgendwo entpacken und Filee.exe starten.`],
  [`Filee doesn't start on Windows 10: no window, no error. What can I do?`,
    `Filee startet unter Windows 10 nicht: kein Fenster, keine Fehlermeldung. Was kann ich tun?`],
  [`This happens on a Windows 10 that hasn't been updated for a long time, on a PC whose processor supports Hardware-enforced Stack Protection (CET). Windows turns that protection on but lacks a part that .NET needs, so Filee and its installer stop right away, without a window or a message. Installing the available Windows updates (the latest cumulative update) fixes it. If updating isn't possible, turning the protection off for Filee alone usually works: in PowerShell as administrator, run Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack, then the same for filee-cli.exe and for the installer's file name (or use the portable ZIP). To undo it, remove those entries in Windows Security → App & browser control → Exploit protection settings → Program settings.`,
    `Das passiert unter einem Windows 10, das lange nicht aktualisiert wurde, auf einem PC, dessen Prozessor hardwaregestützten Stapelschutz (CET) unterstützt. Windows schaltet diesen Schutz ein, ihm fehlt aber ein Teil, den .NET braucht, daher beenden sich Filee und sein Installationsprogramm sofort, ohne Fenster oder Meldung. Die verfügbaren Windows-Updates zu installieren (das neueste kumulative Update) behebt das. Ist kein Update möglich, hilft es meist, den Schutz nur für Filee abzuschalten: Führe in PowerShell als Administrator Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack aus, dann dasselbe für filee-cli.exe und für den Dateinamen des Installationsprogramms (oder nutze die portable ZIP-Datei). Zum Rückgängigmachen entferne diese Einträge unter Windows-Sicherheit → App- & Browsersteuerung → Exploit-Schutz-Einstellungen → Programmeinstellungen.`],
  [`Can I convert many files at once?`, `Kann ich viele Dateien auf einmal konvertieren?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Ja. Wähle beliebig viele Dateien aus und lege sie einmal ab: Filee konvertiert sie parallel, eine fehlgeschlagene Datei hält die anderen nie auf, und Vorlagen können alles in einer PDF zusammenführen oder in eine ZIP-Datei packen.`],
  [`Can I convert from the Windows 11 right-click menu?`,
    `Kann ich über das Rechtsklickmenü von Windows 11 konvertieren?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Ja. Klicke im Explorer mit der rechten Maustaste auf Dateien und wähle „Mit Filee konvertieren“. Unter Windows 11 kannst du den Eintrag auch ins Hauptmenü holen, ohne „Weitere Optionen anzeigen“: Klicke einmal unter Einstellungen → Allgemein auf „Zum Hauptmenü hinzufügen“ und bestätige die Administratorabfrage. „Senden an“, ein Tastenkürzel und der Ablagebereich im Hauptfenster funktionieren ebenfalls.`],
  [`Can Filee convert from the command line or automatically?`,
    `Kann Filee über die Befehlszeile oder automatisch konvertieren?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Ja. Das Installationsprogramm kann den Befehl filee zu PATH hinzufügen: filee convert *.heic --to jpg konvertiert Dateien, Platzhalter und Ordner mit deinen Vorlagen, gibt JSON für Skripte aus und liefert Exit-Codes. Überwachte Ordner konvertieren automatisch die Dateien, die in einem Ordner landen, und können die Originale beiseitelegen. Richte sie auf der Seite „Überwachte Ordner“ in der App oder mit filee watch im Terminal ein.`],
  [`How do I convert a file, for example HEIC to JPG?`, `Wie konvertiere ich eine Datei, etwa HEIC in JPG?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `Wähle die Dateien im Explorer aus, halte Strg (oder die gewählte Taste) gedrückt und ziehe sie. Ein Ringmenü mit Formaten öffnet sich am Mauszeiger: Lege die Dateien auf JPG ab, und die neuen Dateien erscheinen neben den Originalen. Für die häufigsten Konvertierungen gibt es Schritt-für-Schritt-Anleitungen.`],
  [`Why use Filee instead of an online converter?`, `Warum Filee statt eines Online-Konverters?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `Online-Konverter laden deine Dateien auf fremde Server hoch, begrenzen oft Dateigröße und -anzahl und brauchen eine schnelle Verbindung. Filee konvertiert auf deinem PC: Private Dateien bleiben privat, große Videos und Hunderte Dateien sind kein Problem, und es funktioniert ohne Internet, kostenlos und ohne Werbung.`],
  [`Which operating systems are supported?`, `Welche Betriebssysteme werden unterstützt?`],
  [`Windows 10 and 11 (64-bit) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `Windows 10 und 11 (64 Bit) und Linux (x64 und ARM64, Ubuntu 22.04 oder neuer) sind vollwertige Versionen. Unter Linux braucht die Ziehgeste eine X11-Sitzung; unter KDE Plasma mit Wayland ist sie experimentell, und auf anderen Wayland-Desktops funktionieren der Ablagebereich und das Rechtsklickmenü des Dateimanagers. macOS 13 oder neuer (Apple Silicon und Intel) ist eine Vorschau: Die App ist noch nicht notarisiert, daher fragt macOS einmal unter Datenschutz & Sicherheit nach deiner Erlaubnis. Wähle dein System im Download-Bereich.`],
]);
